													@click="hapusBaris(blok.field, ri)"
												>
													Hapus baris
												</button>
											</div>
										</div>

										<button
											v-if="bolehUbahTabel(blok.field)"
											type="button"
											class="w-full rounded-lg border border-dashed border-ui-line-gray-300 py-2.5 text-sm font-medium text-primary transition hover:bg-ui-surface-gray-50"
											@click="tambahBaris(blok.field)"
										>
											+ Tambah baris
