				</template>

				<p v-else class="py-10 text-center text-sm text-ui-ink-gray-400">
					Tidak ada data yang dapat ditampilkan.
				</p>
			</div>

			<!-- ====== Bottom bar: Save (mode edit) — sama dengan Data Pengajuan ====== -->
			<Transition
				enter-active-class="transition duration-200 ease-out"
				enter-from-class="translate-y-2 opacity-0"
				leave-active-class="transition duration-150 ease-in"
				leave-to-class="translate-y-2 opacity-0"
			>
				<div
					v-if="editMode"
					class="bottom-bar sticky bottom-0 z-20 border-t border-ui-line-gray-200 bg-ui-surface px-4 py-3 md:px-6"
				>
					<button
						type="button"
						:disabled="saving"
						class="flex w-full items-center justify-center gap-2 rounded-full bg-primary py-3 text-sm font-semibold text-ui-onPrimary shadow-sm transition active:scale-[0.99] disabled:cursor-not-allowed disabled:opacity-50"
						@click="saveDocument"
					>
						<svg
							v-if="saving"
							xmlns="http://www.w3.org/2000/svg"
							viewBox="0 0 24 24"
							class="h-4 w-4 animate-spin"
							fill="none"
							stroke="currentColor"
							stroke-width="2"
							stroke-linecap="round"
							stroke-linejoin="round"
						>
							<path d="M21 12a9 9 0 1 1-6.219-8.56" />
						</svg>
						{{ saving ? 'Menyimpan…' : 'Save' }}
					</button>
				</div>
			</Transition>
		</template>
