</template>

<script setup>
/**
 * Form berbasis meta doctype — lihat & edit, dengan collapse bercabang:
 *
 *   section (level 1) → tabel anak (level 2) → baris (level 3)
 *
 * Susunan tab/section/kolom/label/tipe/depends_on dibaca dari
 * `frappe.desk.form.load.getdoctype`. Alur edit meniru Data Pengajuan: tombol
 * pensil di header halaman induk (lihat `canEditDoc`/`enterEditMode` yang
 * di-expose), widget per field di MetaField.vue, state `form` + `dirty`,
 * `evalCondition` dengan helper Frappe, dan bar bawah "Save" yang menyimpan
 * lewat `frappe.client.save` lalu kembali ke mode baca.
 *
 * Doctype Single (mis. Pengaturan HR) cukup diberi `name` = nama doctype-nya.
 */
import {
	computed,
	defineComponent,
	h,
	nextTick,
	onMounted,
	provide,
	reactive,
	ref,
	watch,
} from 'vue'
import { refreshCsrfToken } from '../data/session'
import { currentUser } from '../data/user'
import { notifyError, notifySuccess } from '../composables/toast'
import MetaField from './MetaField.vue'

const props = defineProps({
	doctype: { type: String, required: true },
	name: { type: String, required: true },
	stickyTop: { type: Number, default: 0 },
})
const emit = defineEmits(['loaded', 'saved'])

const STRUKTUR = ['Section Break', 'Column Break', 'Tab Break']
const LEWATI = [
	'HTML',
	'Button',
	'Heading',
	'Fold',
	'Barcode',
	'Image',
	'Geolocation',
	'Signature',
]
// Tipe yang tidak pernah diisi tangan.
const TIDAK_BISA_DIUBAH = [
	'Read Only',
	'Table MultiSelect',
	'Duration',
	'Rating',
	'Color',
	'Password',
]

// ---- Ikon panah collapse ---------------------------------------------------
const IkonPanah = defineComponent({
	props: { terbuka: Boolean },
	setup(p) {
		return () =>
			h(
				'svg',
				{
					xmlns: 'http://www.w3.org/2000/svg',
					viewBox: '0 0 24 24',
					class: [
						'h-5 w-5 shrink-0 text-ui-ink-gray-400 transition-transform',
						p.terbuka && 'rotate-180',
					],
					fill: 'none',
					stroke: 'currentColor',
					'stroke-width': 2,
					'stroke-linecap': 'round',
					'stroke-linejoin': 'round',
				},
				[h('path', { d: 'm6 9 6 6 6-6' })]
			)
	},
})

// ---- Data ------------------------------------------------------------------
const memuat = ref(true)
const galatMuat = ref('')
const metaInduk = ref([])
const metaAnak = reactive({})
const writablePermlevels = ref(new Set()) // permlevel yang boleh ditulis user
const docData = ref(null) // dokumen dari server

// Nilai field yang bisa diedit (copy dari dokumen saat load).
const form = reactive({})

// ---- Status "dirty" (sama dengan Data Pengajuan) ---------------------------
// applyingRemote = true saat form diisi dari server → tidak menandai dirty.
const dirty = ref(false)
const applyingRemote = ref(false)
const saving = ref(false)

watch(
	form,
	() => {
		if (!applyingRemote.value) dirty.value = true
	},
	{ deep: true }
)

const salin = (x) => JSON.parse(JSON.stringify(x))

// Sinkronkan form dari dokumen server tanpa memicu dirty.
async function syncFormFromDoc() {
	applyingRemote.value = true
	try {
		for (const k of Object.keys(form)) delete form[k]
		Object.assign(form, salin(docData.value || {}))
		await nextTick()
	} finally {
		applyingRemote.value = false
	}
	dirty.value = false
}

// ---- Mode edit -------------------------------------------------------------
// Doctype ini tanpa workflow: boleh edit = punya izin tulis permlevel 0.
const editMode = ref(false)
const canEditDoc = computed(() => !!docData.value && writablePermlevels.value.has(0))
function enterEditMode() {
	if (canEditDoc.value) editMode.value = true
}
watch(canEditDoc, (can) => {
	if (!can) editMode.value = false
})
defineExpose({ editMode, canEditDoc, enterEditMode })

// ---- Muat meta + dokumen ---------------------------------------------------
async function ambilJson(url) {
	const res = await fetch(url, {
		credentials: 'include',
		headers: { Accept: 'application/json' },
	})
	const json = await res.json().catch(() => ({}))
	if (!res.ok) throw json
	return json
}
async function ambilMeta(dt) {
	const json = await ambilJson(
		`/api/method/frappe.desk.form.load.getdoctype?doctype=${encodeURIComponent(dt)}`
	)
	const docs = json.docs || json.message?.docs || []
	return docs.find((x) => x.name === dt) || docs[0] || {}
}
async function ambilDoc() {
	const json = await ambilJson(
		`/api/method/frappe.client.get?doctype=${encodeURIComponent(
			props.doctype
		)}&name=${encodeURIComponent(props.name)}`
	)
	return json.message
}

async function muat() {
	memuat.value = true
	galatMuat.value = ''
	try {
		const [data, meta, izin] = await Promise.all([
			ambilDoc(),
			ambilMeta(props.doctype),
			ambilJson(
				`/api/method/juragan.api.portal.meta.get_permlevel_access?doctype=${encodeURIComponent(
					props.doctype
				)}`
			).catch(() => ({})),
		])
		writablePermlevels.value = new Set(izin.message?.write || [])
		metaInduk.value = meta.fields || []
		const dtAnak = [
			...new Set(
				metaInduk.value
					.filter((f) => f.fieldtype === 'Table' && f.options)
					.map((f) => f.options)
			),
		]
		await Promise.all(
			dtAnak.map(async (dt) => {
				try {
					metaAnak[dt] = (await ambilMeta(dt)).fields || []
				} catch (e) {
					metaAnak[dt] = []
				}
			})
		)
		docData.value = data
		await syncFormFromDoc()
		emit('loaded', docData.value)
	} catch (e) {
		galatMuat.value = (e && (e.message || e.exception)) || 'Gagal memuat data.'
	} finally {
		memuat.value = false
	}
}

// ---- Kondisi Frappe (sama dengan Data Pengajuan) ---------------------------
// Evaluasi depends_on / mandatory_depends_on / read_only_depends_on terhadap
// dokumen (`doc` = form induk atau baris tabel anak).
function evalCondition(expr, doc) {
	if (!expr) return true
	try {
		const raw = String(expr)
		// Bentuk tanpa "eval:" = nama field → bernilai truthy atau tidak.
		if (!raw.startsWith('eval:')) return !!(doc || {})[raw]
		const code = raw.replace(/^eval:/, '')
		const in_list = (list, item) => Array.isArray(list) && list.includes(item)
		const cint = (v) => parseInt(v, 10) || 0
		const cstr = (v) => (v == null ? '' : String(v))
		const flt = (v) => parseFloat(v) || 0
		const frappe = { session: { user: currentUser.user } }
		// eslint-disable-next-line no-new-func
		return !!new Function(
			'doc',
			'parent',
			'in_list',
			'cint',
			'cstr',
			'flt',
			'frappe',
			`return (${code})`
		)(doc || {}, form, in_list, cint, cstr, flt, frappe)
	} catch (e) {
		return true // gagal evaluasi → tampilkan saja (fail-open)
	}
}
// Field wajib: reqd statis ATAU mandatory_depends_on terpenuhi.
function isFieldReqd(field, doc) {
	if (field.reqd) return true
	return field.mandatory_depends_on ? evalCondition(field.mandatory_depends_on, doc) : false
}
// Read-only murni field-level (tanpa gate editMode), PERSIS desk:
//  1. Tak punya hak tulis permlevel → read-only (menang atas segalanya).
//  2. `read_only_depends_on` ADA → hasilnya menentukan (menimpa read_only statis).
//  3. Selain itu → ikut read_only statis.
function fieldLevelReadOnly(field, doc) {
	if (TIDAK_BISA_DIUBAH.includes(field.fieldtype)) return true
	if (!writablePermlevels.value.has(field.permlevel || 0)) return true
	if (field.read_only_depends_on) return evalCondition(field.read_only_depends_on, doc)
	return !!field.read_only
}
// Field read-only di UI: mode baca selalu read-only; mode edit → aturan field-level.
function isFieldReadOnly(field, doc) {
	if (!editMode.value) return true
	return fieldLevelReadOnly(field, doc)
}

// ---- Judul field Link (title_field, bukan kode) ----------------------------
const linkTitleField = reactive({}) // { doctype: title_field | null }
const linkTitles = reactive({}) // { 'doctype:value': judul }
const sedangDimuat = new Set()

async function titleFieldOf(dt) {
	if (!dt) return null
	if (linkTitleField[dt] !== undefined) return linkTitleField[dt]
	try {
		linkTitleField[dt] = (await ambilMeta(dt)).title_field || null
	} catch (e) {
		linkTitleField[dt] = null
	}
	return linkTitleField[dt]
}
async function resolveLinkTitle(dt, value) {
	const key = `${dt}:${value}`
	if (sedangDimuat.has(key) || linkTitles[key] !== undefined) return
	sedangDimuat.add(key)
	try {
		const titleField = await titleFieldOf(dt)
		if (!titleField) {
			linkTitles[key] = String(value)
			return
		}
		const params = new URLSearchParams({
			doctype: dt,
			fieldname: titleField,
			filters: String(value),
		})
		const json = await ambilJson(`/api/method/frappe.client.get_value?${params.toString()}`)
		const msg = json.message
		const title = msg && typeof msg === 'object' ? msg[titleField] : msg
		linkTitles[key] = title != null && title !== '' ? title : String(value)
	} catch (e) {
		linkTitles[key] = String(value)
	} finally {
		sedangDimuat.delete(key)
	}
}
// Nilai tampilan Link: judul hasil resolusi; doctype tanpa title_field → kode;
// belum ter-resolve → '…' supaya kode tidak berkedip.
function linkDisplay(dt, value) {
	if (value == null || value === '') return ''
	if (!dt) return String(value)
	const t = linkTitles[`${dt}:${value}`]
	if (t !== undefined) return t
	if (linkTitleField[dt] === null) return String(value)
	resolveLinkTitle(dt, value)
	return '…'
}

provide('metaLinkStore', {
	titleFieldOf,
	display: linkDisplay,
	save: (dt, value, label) => {
		linkTitles[`${dt}:${value}`] = label
	},
})
// Satu panel dropdown Link terbuka pada satu waktu di seluruh form.
const openDropdown = ref('')
provide('metaOpenDropdown', openDropdown)

// Tiru `fetch_from` Frappe: saat Link berubah, isi field turunannya langsung.
async function applyFetchFrom(fields, doc, linkField, value) {
	const prefix = `${linkField.fieldname}.`
	const targets = fields.filter(
		(f) => typeof f.fetch_from === 'string' && f.fetch_from.startsWith(prefix)
	)
	if (!targets.length) return
	if (!value) {
		for (const t of targets) doc[t.fieldname] = null
		return
	}
	const dt = linkField.fieldtype === 'Link' ? linkField.options : doc[linkField.options]
	if (!dt) return
	try {
		const params = new URLSearchParams({
			doctype: dt,
			filters: JSON.stringify({ name: value }),
			fieldname: JSON.stringify(targets.map((t) => t.fetch_from.slice(prefix.length))),
		})
		const data =
			(await ambilJson(`/api/method/frappe.client.get_value?${params.toString()}`))
				.message || {}
		for (const t of targets) {
			const src = t.fetch_from.slice(prefix.length)
			if (src in data) doc[t.fieldname] = data[src]
		}
	} catch (e) {
		/* abaikan — nilai tetap ikut terisi server saat save */
	}
}

// ---- Susunan tab → section → blok -----------------------------------------
const tabs = computed(() => {
	const out = []
	let tab = null
	let sec = null
	let blokField = null
	let kol = null
	let secTersembunyi = false

	const pastikanTab = () => {
		if (!tab) {
			tab = { key: '__utama__', label: 'Detail', sections: [] }
			out.push(tab)
		}
	}
	const pastikanSection = () => {
		pastikanTab()
		if (!sec) {
			sec = { key: `${tab.key}:__awal__`, label: '', blocks: [] }
			tab.sections.push(sec)
			blokField = null
		}
	}
	const pastikanKolom = () => {
		pastikanSection()
		if (!blokField) {
			kol = []
			blokField = { type: 'fields', columns: [kol] }
			sec.blocks.push(blokField)
		}
	}

	for (const f of metaInduk.value) {
		const ft = f.fieldtype
		if (ft === 'Tab Break') {
			tab = { key: f.fieldname, label: f.label || f.fieldname, sections: [] }
			out.push(tab)
			sec = null
			blokField = null
			secTersembunyi = false
			continue
		}
		if (ft === 'Section Break') {
			pastikanTab()
			secTersembunyi = !!f.hidden || !evalCondition(f.depends_on, form)
			blokField = null
			if (secTersembunyi) continue
			// Section tanpa judul di desk hanya memulai baris baru di bawah section
			// sebelumnya, tanpa kepala sendiri — di sini digabung ke section itu.
			if (!f.label && sec && tab.sections.includes(sec)) continue
			sec = { key: f.fieldname, label: f.label || '', blocks: [] }
			tab.sections.push(sec)
			continue
		}
		if (secTersembunyi) continue
		if (ft === 'Column Break') {
			if (!blokField) pastikanKolom()
			else {
				kol = []
				blokField.columns.push(kol)
			}
			continue
		}
		if (f.hidden || LEWATI.includes(ft) || !evalCondition(f.depends_on, form)) continue
		if (ft === 'Table') {
			pastikanSection()
			sec.blocks.push({ type: 'table', field: f })
			blokField = null
			continue
		}
		pastikanKolom()
		kol.push(f)
	}

	return out
		.map((t) => ({
			...t,
			sections: t.sections
				.map((s, i) => {
					const blocks = s.blocks.filter(
						(b) => b.type !== 'fields' || b.columns.some((c) => c.length)
					)
					const tabel = blocks.filter((b) => b.type === 'table')
					// Section tanpa judul: pakai judul tabel tunggalnya, atau nama tab.
					const label =
						s.label ||
						(tabel.length === 1 && blocks.length === 1 ? tabel[0].field.label : '') ||
						(i === 0 ? t.label : 'Lainnya')
					return { ...s, label, blocks, jumlahTabel: tabel.length }
				})
				.filter((s) => s.blocks.length),
		}))
		.filter((t) => t.sections.length)
})

const tabAktif = ref('')
const tabAktifObj = computed(() => tabs.value.find((t) => t.key === tabAktif.value))

// ---- Collapse --------------------------------------------------------------
const terbukaSection = reactive(new Set())
const terbukaTabel = reactive(new Set())
const terbukaBaris = reactive(new Set())
const sudahDiatur = new Set()

watch(
	tabs,
	(daftar) => {
		if (!daftar.some((t) => t.key === tabAktif.value)) tabAktif.value = daftar[0]?.key || ''
		// Section pertama tiap tab terbuka saat pertama tampil; sisanya tertutup.
		for (const t of daftar) {
			if (sudahDiatur.has(t.key) || !t.sections.length) continue
			sudahDiatur.add(t.key)
			terbukaSection.add(t.sections[0].key)
		}
	},
	{ immediate: true }
)

function toggle(set, key) {
	if (set.has(key)) set.delete(key)
	else set.add(key)
}
function bukaSemua(buka) {
	const t = tabAktifObj.value
	if (!t) return
	for (const s of t.sections) {
		if (buka) terbukaSection.add(s.key)
		else terbukaSection.delete(s.key)
		for (const b of s.blocks) {
			if (b.type !== 'table') continue
			if (buka) terbukaTabel.add(b.field.fieldname)
			else terbukaTabel.delete(b.field.fieldname)
		}
	}
	if (!buka) terbukaBaris.clear()
}

// ---- Tabel anak ------------------------------------------------------------
function kosong(v) {
	return v == null || (typeof v === 'string' && v.trim() === '')
}
function baris(f) {
	const rows = form[f.fieldname]
	return Array.isArray(rows) ? rows : []
}
function kunciBaris(row, ri) {
	return row.name || row.__kunci || `baru-${ri}`
}
function fieldAnakSemua(dt) {
	return (metaAnak[dt] || []).filter(
		(f) => !STRUKTUR.includes(f.fieldtype) && !LEWATI.includes(f.fieldtype) && !f.hidden
	)
}
function fieldAnak(f, row) {
	return fieldAnakSemua(f.options).filter((cf) => evalCondition(cf.depends_on, row))
}
function tampilRingkas(cf, v) {
	if (['Link', 'Dynamic Link'].includes(cf.fieldtype)) {
		return linkDisplay(cf.fieldtype === 'Link' ? cf.options : null, v)
	}
	const m = String(v || '').match(/^(\d{4})-(\d{2})-(\d{2})/)
	if (['Date', 'Datetime'].includes(cf.fieldtype) && m) return `${m[3]}-${m[2]}-${m[1]}`
	return String(v)
}
function judulBaris(f, row, ri) {
	const daftar = fieldAnakSemua(f.options)
	const utama = daftar.filter((cf) => cf.in_list_view)
	for (const cf of [...utama, ...daftar]) {
		if (
			['Data', 'Select', 'Link', 'Dynamic Link', 'Small Text'].includes(cf.fieldtype) &&
			!kosong(row[cf.fieldname])
		)
			return tampilRingkas(cf, row[cf.fieldname])
	}
	return `Baris ${ri + 1}`
}
function subjudulBaris(f, row) {
	const cf = fieldAnakSemua(f.options).find(
		(x) =>
			x.in_list_view &&
			['Date', 'Datetime'].includes(x.fieldtype) &&
			!kosong(row[x.fieldname])
	)
	return cf ? `${cf.label}: ${tampilRingkas(cf, row[cf.fieldname])}` : ''
}

// Tabel boleh diubah (tambah/hapus baris) bila sedang mode edit dan field
// tabelnya tidak read-only (permlevel / read_only / read_only_depends_on).
function bolehUbahTabel(f) {
	return editMode.value && !fieldLevelReadOnly(f, form)
}

let nomorBaru = 0
function nilaiBawaan(cf) {
	if (cf.default == null || cf.default === '') return cf.fieldtype === 'Check' ? 0 : null
	if (cf.default === 'Today') return new Date().toISOString().slice(0, 10)
	if (cf.fieldtype === 'Check') return Number(cf.default) ? 1 : 0
	return cf.default
}
function tambahBaris(f) {
	if (!Array.isArray(form[f.fieldname])) form[f.fieldname] = []
	const row = {
		doctype: f.options,
		parentfield: f.fieldname,
		parenttype: props.doctype,
		__islocal: 1,
		__kunci: `baru-${++nomorBaru}`,
	}
	for (const cf of fieldAnakSemua(f.options)) row[cf.fieldname] = nilaiBawaan(cf)
	form[f.fieldname].push(row)
	terbukaTabel.add(f.fieldname)
	terbukaBaris.add(row.__kunci)
}
function hapusBaris(f, ri) {
	form[f.fieldname].splice(ri, 1)
}

// ---- Simpan (sama dengan Data Pengajuan) -----------------------------------
// Simpan dokumen via frappe.client.save (POST → butuh CSRF).
async function saveDoc(docObj) {
	const res = await fetch('/api/method/frappe.client.save', {
		method: 'POST',
		credentials: 'include',
		headers: {
			'Content-Type': 'application/json',
			Accept: 'application/json',
			'X-Frappe-CSRF-Token': window.csrf_token || '',
		},
		body: JSON.stringify({ doc: docObj }),
	})
	const json = await res.json().catch(() => ({}))
	if (!res.ok) throw json
	return json.message
}

async function saveDocument() {
	saving.value = true
	try {
		await refreshCsrfToken()
		const payload = salin(form)
		for (const v of Object.values(payload)) {
			if (Array.isArray(v)) v.forEach((r) => delete r.__kunci)
		}
		payload.doctype = props.doctype
		payload.name = docData.value.name
		await saveDoc(payload)
		docData.value = await ambilDoc()
		await syncFormFromDoc() // sinkron nilai server + reset dirty
		editMode.value = false // selesai simpan → kembali ke mode baca
		emit('saved', docData.value)
		notifySuccess('Perubahan berhasil disimpan.')
	} catch (e) {
		notifyError(e, 'Gagal menyimpan')
	} finally {
		saving.value = false
	}
}

watch(
	() => [props.doctype, props.name],
	() => {
		editMode.value = false
		muat()
	}
)
onMounted(async () => {
	await refreshCsrfToken()
	muat()
})
</script>
